-- BECE French Questions - 2024 (40 questions)
INSERT OR REPLACE INTO questions (id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, options, correct_answer, explanation, difficulty, marks, question_number) VALUES
-- Greetings and Basic Expressions (Questions 1-10)
('q_bece_french_2024_001', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'How do you say "Good morning" in French?', 'multiple_choice', '["A. Bonsoir", "B. Bonjour", "C. Bonne nuit", "D. Salut"]', 'B', 'Bonjour means "Good morning" or "Good day." Bonsoir means "Good evening," Bonne nuit means "Good night," and Salut is informal "Hi."', 'easy', 1, 1),
('q_bece_french_2024_002', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'What is "Comment allez-vous?" in English?', 'multiple_choice', '["A. What is your name?", "B. How are you?", "C. Where are you going?", "D. How old are you?"]', 'B', 'Comment allez-vous? is the formal way to ask "How are you?" in French.', 'easy', 1, 2),
('q_bece_french_2024_003', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'Complete: Je m''appelle _____ (My name is Kofi)', 'multiple_choice', '["A. Kofi", "B. est Kofi", "C. suis Kofi", "D. appelle Kofi"]', 'A', 'Je m''appelle is followed directly by the name. Je m''appelle Kofi means "My name is Kofi."', 'easy', 1, 3),
('q_bece_french_2024_004', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Au revoir" means:', 'multiple_choice', '["A. Hello", "B. Please", "C. Goodbye", "D. Thank you"]', 'C', 'Au revoir means "Goodbye" in French. It literally translates to "Until we see each other again."', 'easy', 1, 4),
('q_bece_french_2024_005', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'How do you say "Thank you" in French?', 'multiple_choice', '["A. Pardon", "B. S''il vous plaît", "C. De rien", "D. Merci"]', 'D', 'Merci means "Thank you." Pardon means "Excuse me," S''il vous plaît means "Please," and De rien means "You''re welcome."', 'easy', 1, 5),
('q_bece_french_2024_006', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"S''il vous plaît" is used to say:', 'multiple_choice', '["A. Thank you", "B. Excuse me", "C. Please", "D. Sorry"]', 'C', 'S''il vous plaît (formal) or S''il te plaît (informal) means "Please" in French.', 'easy', 1, 6),
('q_bece_french_2024_007', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'To respond "I am fine" in French, you say:', 'multiple_choice', '["A. Je vais bien", "B. Je suis content", "C. Je m''appelle bien", "D. Je peux bien"]', 'A', 'Je vais bien means "I am fine" or "I am doing well." It is the response to Comment allez-vous?', 'easy', 1, 7),
('q_bece_french_2024_008', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Excusez-moi" is used when you want to:', 'multiple_choice', '["A. Say goodbye", "B. Apologize or get attention", "C. Introduce yourself", "D. Ask the time"]', 'B', 'Excusez-moi means "Excuse me" and is used to apologize or politely get someone''s attention.', 'easy', 1, 8),
('q_bece_french_2024_009', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'What does "Bonne nuit" mean?', 'multiple_choice', '["A. Good morning", "B. Good afternoon", "C. Good evening", "D. Good night"]', 'D', 'Bonne nuit means "Good night" and is said when going to bed.', 'easy', 1, 9),
('q_bece_french_2024_010', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Et vous?" means:', 'multiple_choice', '["A. And you?", "B. Yes, please", "C. Not at all", "D. See you"]', 'A', 'Et vous? (formal) or Et toi? (informal) means "And you?" Used to return a question.', 'easy', 1, 10),

-- Numbers and Time (Questions 11-18)
('q_bece_french_2024_011', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'What is "quinze" in English?', 'multiple_choice', '["A. Five", "B. Fourteen", "C. Fifteen", "D. Fifty"]', 'C', 'Quinze means fifteen (15) in French.', 'easy', 1, 11),
('q_bece_french_2024_012', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'How do you write 21 in French?', 'multiple_choice', '["A. Vingt", "B. Vingt et un", "C. Deux un", "D. Vingt-deux"]', 'B', 'Twenty-one in French is vingt et un (20 and 1).', 'medium', 1, 12),
('q_bece_french_2024_013', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Quelle heure est-il?" means:', 'multiple_choice', '["A. What day is it?", "B. What time is it?", "C. What date is it?", "D. What year is it?"]', 'B', 'Quelle heure est-il? means "What time is it?" in French.', 'easy', 1, 13),
('q_bece_french_2024_014', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'Il est trois heures means:', 'multiple_choice', '["A. It is 2 o''clock", "B. It is 3 o''clock", "C. It is 4 o''clock", "D. It is 13 o''clock"]', 'B', 'Il est trois heures means "It is three o''clock." Trois = three, heures = hours/o''clock.', 'easy', 1, 14),
('q_bece_french_2024_015', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Soixante" is the French word for:', 'multiple_choice', '["A. Sixteen", "B. Seventeen", "C. Sixty", "D. Seventy"]', 'C', 'Soixante means sixty (60) in French. Seize means sixteen.', 'medium', 1, 15),
('q_bece_french_2024_016', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'What is "midi" in English?', 'multiple_choice', '["A. Midnight", "B. Midday/Noon", "C. Morning", "D. Evening"]', 'B', 'Midi means midday or noon (12:00 PM). Minuit means midnight.', 'easy', 1, 16),
('q_bece_french_2024_017', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'How do you say "Monday" in French?', 'multiple_choice', '["A. Mardi", "B. Mercredi", "C. Lundi", "D. Dimanche"]', 'C', 'Lundi is Monday in French. Mardi is Tuesday, Mercredi is Wednesday, and Dimanche is Sunday.', 'easy', 1, 17),
('q_bece_french_2024_018', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Janvier" is the French word for:', 'multiple_choice', '["A. June", "B. July", "C. January", "D. February"]', 'C', 'Janvier means January. Juin is June, Juillet is July, and Février is February.', 'easy', 1, 18),

-- Family and Personal Information (Questions 19-25)
('q_bece_french_2024_019', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Ma mère" means:', 'multiple_choice', '["A. My father", "B. My mother", "C. My sister", "D. My brother"]', 'B', 'Ma mère means "my mother." Mon père means "my father."', 'easy', 1, 19),
('q_bece_french_2024_020', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'How do you say "my brother" in French?', 'multiple_choice', '["A. Ma soeur", "B. Mon frère", "C. Mon père", "D. Mon oncle"]', 'B', 'Mon frère means "my brother." Ma soeur means "my sister."', 'easy', 1, 20),
('q_bece_french_2024_021', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"J''ai douze ans" means:', 'multiple_choice', '["A. I have twelve books", "B. I am twelve years old", "C. I live at number twelve", "D. It is twelve o''clock"]', 'B', 'J''ai douze ans literally means "I have twelve years," which is how French expresses "I am twelve years old."', 'easy', 1, 21),
('q_bece_french_2024_022', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'To ask "How old are you?" in French, you say:', 'multiple_choice', '["A. Quel âge as-tu?", "B. Où habites-tu?", "C. Comment t''appelles-tu?", "D. D''où viens-tu?"]', 'A', 'Quel âge as-tu? (informal) or Quel âge avez-vous? (formal) means "How old are you?"', 'easy', 1, 22),
('q_bece_french_2024_023', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Mes grands-parents" refers to:', 'multiple_choice', '["A. My parents", "B. My grandparents", "C. My grandchildren", "D. My great-parents"]', 'B', 'Mes grands-parents means "my grandparents." Grand-père is grandfather, grand-mère is grandmother.', 'easy', 1, 23),
('q_bece_french_2024_024', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'How do you say "I live in Accra" in French?', 'multiple_choice', '["A. Je suis d''Accra", "B. J''habite à Accra", "C. Je vais à Accra", "D. Je visite Accra"]', 'B', 'J''habite à Accra means "I live in Accra." Habiter means to live/reside.', 'medium', 1, 24),
('q_bece_french_2024_025', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Ma famille" means:', 'multiple_choice', '["A. My friend", "B. My family", "C. My school", "D. My house"]', 'B', 'Ma famille means "my family." Famille is a feminine noun.', 'easy', 1, 25),

-- School and Daily Life (Questions 26-32)
('q_bece_french_2024_026', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"L''école" is the French word for:', 'multiple_choice', '["A. The book", "B. The class", "C. The school", "D. The teacher"]', 'C', 'L''école means "the school." École is a feminine noun.', 'easy', 1, 26),
('q_bece_french_2024_027', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'How do you say "the book" in French?', 'multiple_choice', '["A. Le cahier", "B. Le livre", "C. Le stylo", "D. La table"]', 'B', 'Le livre means "the book." Le cahier is "the notebook," le stylo is "the pen."', 'easy', 1, 27),
('q_bece_french_2024_028', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Le professeur" means:', 'multiple_choice', '["A. The student", "B. The principal", "C. The teacher", "D. The parent"]', 'C', 'Le professeur means "the teacher." L''élève means "the student."', 'easy', 1, 28),
('q_bece_french_2024_029', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'To say "I am a student" in French:', 'multiple_choice', '["A. Je suis professeur", "B. Je suis élève", "C. Je suis directeur", "D. Je suis médecin"]', 'B', 'Je suis élève means "I am a student." In French, articles are often omitted with professions and occupations.', 'easy', 1, 29),
('q_bece_french_2024_030', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"La classe" refers to:', 'multiple_choice', '["A. The glass", "B. The classroom/class", "C. The classic", "D. The lesson"]', 'B', 'La classe means "the class" or "the classroom."', 'easy', 1, 30),
('q_bece_french_2024_031', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'How do you say "I study French" in French?', 'multiple_choice', '["A. J''étudie le français", "B. Je parle français", "C. J''aime le français", "D. Je lis le français"]', 'A', 'J''étudie le français means "I study French." Étudier means to study.', 'medium', 1, 31),
('q_bece_french_2024_032', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Je comprends" means:', 'multiple_choice', '["A. I read", "B. I write", "C. I understand", "D. I listen"]', 'C', 'Je comprends means "I understand." Comprendre is an irregular verb meaning to understand.', 'medium', 1, 32),

-- Food and Colors (Questions 33-40)
('q_bece_french_2024_033', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Le pain" is the French word for:', 'multiple_choice', '["A. Water", "B. Bread", "C. Rice", "D. Meat"]', 'B', 'Le pain means "bread" in French. L''eau is water, le riz is rice.', 'easy', 1, 33),
('q_bece_french_2024_034', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'How do you say "water" in French?', 'multiple_choice', '["A. Le lait", "B. Le jus", "C. L''eau", "D. Le thé"]', 'C', 'L''eau means "water." Le lait is milk, le jus is juice, le thé is tea.', 'easy', 1, 34),
('q_bece_french_2024_035', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"J''ai faim" means:', 'multiple_choice', '["A. I am tired", "B. I am thirsty", "C. I am hungry", "D. I am happy"]', 'C', 'J''ai faim literally means "I have hunger," expressing "I am hungry." J''ai soif means "I am thirsty."', 'easy', 1, 35),
('q_bece_french_2024_036', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Rouge" is the French word for which color?', 'multiple_choice', '["A. Blue", "B. Green", "C. Yellow", "D. Red"]', 'D', 'Rouge means red. Bleu is blue, vert is green, jaune is yellow.', 'easy', 1, 36),
('q_bece_french_2024_037', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'What color is "blanc"?', 'multiple_choice', '["A. Black", "B. White", "C. Brown", "D. Gray"]', 'B', 'Blanc means white. Noir is black, marron/brun is brown, gris is gray.', 'easy', 1, 37),
('q_bece_french_2024_038', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"Je voudrais" is used to:', 'multiple_choice', '["A. Express anger", "B. Politely request something", "C. Greet someone", "D. Say goodbye"]', 'B', 'Je voudrais means "I would like" and is a polite way to request something.', 'medium', 1, 38),
('q_bece_french_2024_039', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', 'How do you say "I like" in French?', 'multiple_choice', '["A. J''aime", "B. Je déteste", "C. Je préfère", "D. Je mange"]', 'A', 'J''aime means "I like" or "I love." Je déteste means "I hate," Je préfère means "I prefer."', 'easy', 1, 39),
('q_bece_french_2024_040', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2024_1', '"C''est délicieux" means:', 'multiple_choice', '["A. It is expensive", "B. It is delicious", "C. It is difficult", "D. It is different"]', 'B', 'C''est délicieux means "It is delicious." Used to compliment food.', 'easy', 1, 40),

-- BECE French Questions - 2023 (40 questions)
-- Basic Vocabulary (Questions 1-10)
('q_bece_french_2023_001', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', 'What is "Oui" in English?', 'multiple_choice', '["A. No", "B. Yes", "C. Maybe", "D. Please"]', 'B', 'Oui means "Yes" in French. Non means "No."', 'easy', 1, 1),
('q_bece_french_2023_002', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', '"Non" means:', 'multiple_choice', '["A. Now", "B. None", "C. No", "D. Noon"]', 'C', 'Non means "No" in French.', 'easy', 1, 2),
('q_bece_french_2023_003', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', 'How do you say "Hello" informally in French?', 'multiple_choice', '["A. Bonjour", "B. Salut", "C. Bonsoir", "D. Au revoir"]', 'B', 'Salut is the informal way to say "Hello" or "Hi" in French.', 'easy', 1, 3),
('q_bece_french_2023_004', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', '"Je ne comprends pas" means:', 'multiple_choice', '["A. I understand", "B. I don''t understand", "C. I don''t know", "D. I don''t speak French"]', 'B', 'Je ne comprends pas means "I don''t understand." Ne...pas is the negative construction.', 'medium', 1, 4),
('q_bece_french_2023_005', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', 'How do you say "You''re welcome" in French?', 'multiple_choice', '["A. Merci", "B. S''il vous plaît", "C. De rien", "D. Pardon"]', 'C', 'De rien means "You''re welcome" or "It''s nothing."', 'easy', 1, 5),
('q_bece_french_2023_006', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', '"Très bien" means:', 'multiple_choice', '["A. Very bad", "B. Very good/well", "C. Not bad", "D. So-so"]', 'B', 'Très bien means "Very good" or "Very well."', 'easy', 1, 6),
('q_bece_french_2023_007', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', 'What does "Enchanté" express?', 'multiple_choice', '["A. Goodbye", "B. Nice to meet you", "C. See you later", "D. Have a good day"]', 'B', 'Enchanté means "Nice to meet you" or "Pleased to meet you."', 'easy', 1, 7),
('q_bece_french_2023_008', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', '"À bientôt" means:', 'multiple_choice', '["A. Goodbye forever", "B. Good luck", "C. See you soon", "D. Good morning"]', 'C', 'À bientôt means "See you soon." It''s a casual farewell.', 'easy', 1, 8),
('q_bece_french_2023_009', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', 'How do you say "Please repeat" in French?', 'multiple_choice', '["A. Répétez, s''il vous plaît", "B. Parlez lentement", "C. Plus vite", "D. Écrivez, s''il vous plaît"]', 'A', 'Répétez, s''il vous plaît means "Please repeat." Used when you didn''t hear or understand.', 'medium', 1, 9),
('q_bece_french_2023_010', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', '"Je suis" translates to:', 'multiple_choice', '["A. I have", "B. I am", "C. I go", "D. I can"]', 'B', 'Je suis means "I am." Suis is the first person singular form of être (to be).', 'easy', 1, 10),

-- Numbers and Quantities (Questions 11-18)
('q_bece_french_2023_011', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', 'What is "dix" in numbers?', 'multiple_choice', '["A. 2", "B. 6", "C. 10", "D. 12"]', 'C', 'Dix means ten (10) in French.', 'easy', 1, 11),
('q_bece_french_2023_012', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', 'How do you write 100 in French?', 'multiple_choice', '["A. Dix", "B. Cent", "C. Mille", "D. Million"]', 'B', 'Cent means one hundred (100). Mille is one thousand.', 'easy', 1, 12),
('q_bece_french_2023_013', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', '"Trente" is the French word for:', 'multiple_choice', '["A. Thirteen", "B. Three", "C. Thirty", "D. Thirty-three"]', 'C', 'Trente means thirty (30). Treize means thirteen, trois means three.', 'easy', 1, 13),
('q_bece_french_2023_014', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', 'What number is "quarante-cinq"?', 'multiple_choice', '["A. 14", "B. 40", "C. 45", "D. 54"]', 'C', 'Quarante-cinq means forty-five (45). Quarante is 40, cinq is 5.', 'medium', 1, 14),
('q_bece_french_2023_015', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', '"Premier" means:', 'multiple_choice', '["A. Last", "B. Second", "C. First", "D. Third"]', 'C', 'Premier means "first" (ordinal). Deuxième is second, troisième is third, dernier is last.', 'easy', 1, 15),
('q_bece_french_2023_016', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', 'How do you say "few" or "a little" in French?', 'multiple_choice', '["A. Beaucoup", "B. Peu", "C. Trop", "D. Très"]', 'B', 'Peu means "few" or "a little." Beaucoup means "a lot," trop means "too much."', 'medium', 1, 16),
('q_bece_french_2023_017', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', '"Beaucoup" means:', 'multiple_choice', '["A. A little", "B. A lot/many", "C. None", "D. Some"]', 'B', 'Beaucoup means "a lot" or "many." J''ai beaucoup d''amis = I have many friends.', 'easy', 1, 17),
('q_bece_french_2023_018', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', 'What day is "samedi"?', 'multiple_choice', '["A. Sunday", "B. Saturday", "C. Friday", "D. Thursday"]', 'B', 'Samedi is Saturday. Dimanche is Sunday, vendredi is Friday.', 'easy', 1, 18),

-- Places and Directions (Questions 19-26)
('q_bece_french_2023_019', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', '"La maison" means:', 'multiple_choice', '["A. The market", "B. The house", "C. The hospital", "D. The church"]', 'B', 'La maison means "the house" or "home."', 'easy', 1, 19),
('q_bece_french_2023_020', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', 'How do you say "the market" in French?', 'multiple_choice', '["A. La banque", "B. Le marché", "C. L''hôpital", "D. La gare"]', 'B', 'Le marché means "the market." La banque is the bank.', 'easy', 1, 20),
('q_bece_french_2023_021', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', '"L''hôpital" refers to:', 'multiple_choice', '["A. The hotel", "B. The hospital", "C. The house", "D. The hall"]', 'B', 'L''hôpital means "the hospital." L''hôtel means "the hotel."', 'easy', 1, 21),
('q_bece_french_2023_022', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', 'To ask "Where is...?" in French, you say:', 'multiple_choice', '["A. Qui est...?", "B. Quand est...?", "C. Où est...?", "D. Comment est...?"]', 'C', 'Où est...? means "Where is...?" Où means "where."', 'easy', 1, 22),
