('q_bece_french_2023_024', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', '"Tout droit" means:', 'multiple_choice', '["A. Turn around", "B. Go back", "C. Straight ahead", "D. Stop here"]', 'C', 'Tout droit means "straight ahead." Used when giving directions.', 'easy', 1, 24),
('q_bece_french_2023_025', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', '"La rue" is the French word for:', 'multiple_choice', '["A. The road", "B. The street", "C. The river", "D. The roof"]', 'B', 'La rue means "the street." La route means "the road."', 'easy', 1, 25),
('q_bece_french_2023_026', 'subj_bece_french', 'exam_bece', 'paper_bece_1', 'pp_bece_french_2023_1', 'How do you say "the city" in French?', 'multiple_choice', '["A. Le village", "B. La ville", "C. Le pays", "D. La région"]', 'B', 'La ville means "the city" or "the town." Le village means "the village."', 'easy', 1, 26),

